examples.template:
CompositionLocalProvider(LocalConfiguration provides locale) {
    MonarchSectionCard(title = {{title}}, meta = {{dateLabel}}) {
        MonarchText(text = {{schedule}}, style = MonarchTextStyle.Label)
        MonarchAgendaList(
            events = listOf(
                MonarchAgendaEvent(id = {{events.0.id}}, title = {{events.0.title}}, start = {{events.0.start|millis}}, end = {{events.0.end|millis}}, detail = {{events.0.detail}}),
                MonarchAgendaEvent(id = {{events.1.id}}, title = {{events.1.title}}, start = {{events.1.start|millis}}, end = {{events.1.end|millis}}),
            ),
            modifier = Modifier.height(160.dp),
            from = {{today|millis}},
            days = 1,
            today = {{today|millis}},
            timeZone = {{timeZone}},
        )
        MonarchText(text = {{dueToday}}, style = MonarchTextStyle.Label)
        Row(verticalAlignment = Alignment.CenterVertically) {
            MonarchCheckboxRow(
                checked = {{tasks.0.id}} in done,
                onCheckedChange = { on -> done = if (on) done + {{tasks.0.id}} else done - {{tasks.0.id}} },
                label = {{tasks.0.title}},
                modifier = Modifier.weight(1f),
            )
            if ({{tasks.0.overdue}}) MonarchBadge(text = {{overdueLabel}}, tone = MonarchTone.Danger)
            MonarchText(text = {{tasks.0.due}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        }
        MonarchCheckboxRow(
            checked = {{tasks.1.id}} in done,
            onCheckedChange = { on -> done = if (on) done + {{tasks.1.id}} else done - {{tasks.1.id}} },
            label = {{tasks.1.title}},
            description = {{tasks.1.detail}},
        )
        Row(verticalAlignment = Alignment.CenterVertically) {
            MonarchCheckboxRow(
                checked = {{tasks.2.id}} in done,
                onCheckedChange = { on -> done = if (on) done + {{tasks.2.id}} else done - {{tasks.2.id}} },
                label = {{tasks.2.title}},
                modifier = Modifier.weight(1f),
            )
            MonarchBadge(text = {{tasks.2.badge.text}}, tone = {{tasks.2.badge.tone|tone}})
        }
    }
}

examples.setupTemplate:
var done by rememberSaveable { mutableStateOf(setOf<String>()) }
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

